            return {"state": "succeeded", "result": result}
        except Exception:
            if attempt == MAX_ATTEMPTS:
                return {"state": "failed"}
            # exponential backoff before the next attempt
            wait = BACKOFF_BASE_SECONDS * (2 ** (attempt - 1))
